def axis(s, a, f):
    from scipy.sparse import lil_matrix
    k = f * np.asarray(s['kappa_' + a])
    n = len(k)
    h = s['L' + a] / n
    v = np.broadcast_to(s['vel_' + a], (n,))
    R = np.broadcast_to(s['reaction_' + a], (n,))
    r = s['robin_' + a]
    A = lil_matrix((n, n))
    for i in range(n):
        A[i, i] = R[i] + abs(v[i]) / h
        for j in (i - 1, i + 1):
            if 0 <= j < n:
                d = 2 / (1 / k[i] + 1 / k[j]) / h ** 2
                A[i, i] += d
                A[i, j] = -d - (abs(v[i]) / h if (j - i) * v[i] < 0 else 0)
        if i in (0, n - 1):
            A[i, i] += r / (h * (1 + r * h / (2 * k[i])))
    return A.tocsc()

def _build_1d(L, n, kappa, vel, robin, diag_add):
    k = np.asarray(kappa, dtype=float)
    h = L / n
    faces = 2 * k[:-1] * k[1:] / ((k[:-1] + k[1:]) * h ** 2)
    positive = np.maximum(vel, 0) / h
    negative = np.maximum(-np.asarray(vel), 0) / h
    diag = np.asarray(diag_add) + np.r_[faces, 0.0] + np.r_[0.0, faces] + positive + negative
    for i in (0, n - 1):
        diag[i] += robin * k[i] / (h * (0.5 * robin * h + k[i]))
    return np.diag(diag) - np.diag(faces + negative[:-1], 1) - np.diag(faces + positive[1:], -1)

def _residualize(z, ridge, columns):
    q, d, _ = np.linalg.svd(z, full_matrices=False)
    fraction = np.divide(d * d, d * d + ridge, out=np.zeros_like(d), where=d * d + ridge > 0)
    return columns - q @ (fraction[:, None] * (q.T @ columns))
